227	    /**
228	     * 계좌이체 결제 생성
229	     *
230	     * @param order      주문 정보
231	     * @param user       사용자 정보
232	     * @param requestDto 계좌이체 결제 요청 DTO
233	     * @return 생성된 계좌이체 결제 정보
234	     * @throws PaymentException 결제 처리 실패 시
235	     */
236	    private Payment createAccountPayment(Order order, User user, AccountPaymentRequestDto requestDto) {
237	        Instant start = Instant.now();
238	        try {
239	            log.info("계좌이체 결제 처리 시작: 주문ID={}, 은행={}",
240	                    order.getId(), requestDto.getBankName());
241	
242	            // 은행 유효성 검증
243	            try {
244	                validateBank(requestDto.getBankName());
245	            } catch (Exception e) {
246	                throw new PaymentException(PaymentErrorCode.INVALID_BANK_INFO,
247	                        "유효하지 않은 은행 정보: " + requestDto.getBankName());
248	            }
249	
250	            AccountPayment accountPayment = AccountPayment.builder()
251	                    .bankName(requestDto.getBankName())
252	                    .accountNumber(requestDto.getAccountNumber())
253	                    .accountHolder(requestDto.getAccountHolder())
254	                    .receiptRequested(requestDto.isReceiptRequested())
255	                    .paidAmount(requestDto.getPaidAmount())
256	                    .build();
257	
258	            accountPayment.assignOrder(order);
259	            accountPayment.assignUser(user);
260	            accountPayment.updateStatus(PaymentStatus.PENDING);
261	
262	            AccountPayment savedPayment = (AccountPayment) paymentRepository.save(accountPayment);
263	            log.info("계좌이체 결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
264	                    order.getId(), savedPayment.getId(), savedPayment.getStatus());
265	
266	            // 처리 시간 로깅
267	            Instant end = Instant.now();
268	            Duration duration = Duration.between(start, end);
269	            log.debug("계좌이체 결제 처리 시간: {}ms", duration.toMillis());
270	
271	            return savedPayment;
272	        } catch (PaymentException e) {
273	            throw e; // 이미 PaymentException이면 그대로 전파
274	        } catch (Exception e) {
275	            log.error("계좌이체 결제 처리 중 예상치 못한 오류 발생: 주문ID={}, 오류={}",
276	                    order.getId(), e.getMessage(), e);
277	            throw new PaymentProcessingException("계좌이체 결제 처리 중 오류가 발생했습니다: " + e.getMessage());
278	        }
279	    }
